mapper.select:
SELECT n.id,n.request_id,n.state_version,n.message_key,n.delivered_at::text FROM auth_governance.request_site_notice n
JOIN auth_governance.access_request r ON r.id=n.request_id WHERE r.tenant_id=#{p.tenantId} AND r.application_id=#{p.applicationId} AND r.environment=#{p.environment}
AND r.membership_id=#{member} AND r.generation=#{generation} AND n.id > #{after} ORDER BY n.id LIMIT 100
